parameters.jsCode:
const response = $input.item.json;
let raw = "";
try {
  raw = response.content[0].text;
} catch (e) {
  return { json: {
    messages: ["(empty Claude response - check API node)"],
    messages_count: 1,
    notes: "ERROR: could not extract text from Claude API response",
    parse_status: "extract_failed",
    should_send_payment: false,
    payment_amount: 0,
    payment_summary: "",
    break_condition: { hit: false },
    raw_response: JSON.stringify(response),
    customer_phone: $('Build Prompt').item.json.customerPhone,
    customer_name: $('Build Prompt').item.json.customerName,
    user_message: $('Build Prompt').item.json.userMessage,
    conversation_history: $('Build Prompt').item.json.conversationHistory,
    history_count: $('Build Prompt').item.json.historyCount,
  should_send_file: !!(parsed && parsed.should_send_file === true),
  file_key: (parsed && typeof parsed.file_key === 'string')
    ? parsed.file_key.trim() : '',
  file_description: (parsed && typeof parsed.file_description === 'string')
    ? parsed.file_description.trim() : '',
  } };
}
let cleaned = raw.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
let parsed;
let parseStatus = "ok";
try {
  parsed = JSON.parse(cleaned);
  if (!Array.isArray(parsed.messages) || parsed.messages.length === 0) throw new Error("messages array missing or empty");
} catch (e) {
  parsed = { messages: [raw], notes_for_zayn: "(JSON parse failed - Claude returned plain text. Error: " + e.message + ")" };
  parseStatus = "fallback_plain_text";
}
let messages = parsed.messages.slice(0, 4).map(m => String(m));
// PAYMENT-URL GUARD: the system prompt forbids the LLM from pasting
// `pay.nomodapp.com` (Build Payment Message appends the real URL when
// should_send_payment fires). The LLM still occasionally writes a bare
// placeholder — operator-visible bug. Strip it deterministically here,
// before Queue & Format / Build Payment Message / autosend sees it.
const __badPatterns = [
  /https?:\/\/pay\.nomodapp\.com[\w\/?=&%-]*/gi,
  /pay\.nomodapp\.com[\w\/?=&%-]*/gi,
  /\[link\]/gi,
  /\[payment\s*link\]/gi,
  /\[insert\s*link\]/gi
];
let __scrubbed = false;
messages = messages.map(m => {
  let out = m;
  for (const p of __badPatterns) {
    p.lastIndex = 0;
    if (p.test(out)) { __scrubbed = true; p.lastIndex = 0; out = out.replace(p, ""); }
  }
  // Clean up dangling fragments left behind after URL removal
  out = out.replace(/:\s*[\u2014\u2013\-]\s*/g, " — ");           // ": — " -> " — "
  out = out.replace(/:\s*(and|so|then|once)\b/gi, " $1");          // ": and we'll..." -> " and we'll..."
  out = out.replace(/(here'?s the (payment )?link[^:.!?]*:\s*\.?)$/i, "want me to send the payment link to lock it in?");
  out = out.replace(/:\s*$/g, "");                                  // trailing colon
  out = out.replace(/\s{2,}/g, " ").trim();
  // If the result still ends with "payment link" / "link" but no URL, swap to CTA
  if (__scrubbed && /\b(payment link|the link)\s*[.!?]?$/i.test(out)) {
    out = "want me to send the payment link to lock it in?";
  }
  if (!out || out.length < 6) out = "want me to send the payment link to lock it in?";
  return out;
});
return { json: {
  messages: messages,
  messages_count: messages.length,
  payment_url_scrubbed: __scrubbed,
  notes: parsed.notes_for_zayn || "(no notes)",
  break_condition: (parsed && parsed.break_condition && typeof parsed.break_condition.hit === 'boolean')
    ? parsed.break_condition : { hit: false },
  should_send_payment: !!(parsed && parsed.should_send_payment === true),
  payment_amount: (parsed && Number(parsed.payment_amount)) || 0,
  payment_summary: (parsed && typeof parsed.payment_summary === "string")
    ? parsed.payment_summary : "",
  parse_status: parseStatus,
  raw_response: raw,
  customer_phone: $('Build Prompt').item.json.customerPhone,
  customer_name: $('Build Prompt').item.json.customerName,
  user_message: $('Build Prompt').item.json.userMessage,
  conversation_history: $('Build Prompt').item.json.conversationHistory,
  history_count: $('Build Prompt').item.json.historyCount,
  should_send_file: !!(parsed && parsed.should_send_file === true),
  file_key: (parsed && typeof parsed.file_key === 'string')
    ? parsed.file_key.trim() : '',
  file_description: (parsed && typeof parsed.file_description === 'string')
    ? parsed.file_description.trim() : ''
} };

// feature-header: Customer Facts sits between Parse Response and this
// node, so $input here is the Customer Facts HTTP response. Resolve the
// draft data from whichever parse node actually ran.
let input;
try { input = $('Parse Response').item.json; }
catch (e) { input = $('Parse Lead Response').item.json; }
let customerHeader = '';
try { customerHeader = ($('Customer Facts').item.json || {}).customer_header || ''; }
catch (e) { customerHeader = ''; }
// Nomod: when the payment branch ran, use its message + header
let paymentMessage = null, paymentHeader = '';
try {
  const __pm = $('Build Payment Message').item.json;
  if (__pm && __pm.payment_message) {
    paymentMessage = String(__pm.payment_message);
    paymentHeader = __pm.payment_header || '';
  }
} catch (e) { paymentMessage = null; }
const data = $getWorkflowStaticData('global');
if (!Array.isArray(data.pendingQueue)) data.pendingQueue = [];

const id = $now.toMillis().toString() + '_' + Math.random().toString(36).slice(2, 7);
const messages = paymentMessage
  ? [paymentMessage]
  : ((Array.isArray(input.messages) && input.messages.length)
      ? input.messages.map(m => String(m))
      : ['(empty draft)']);
const hc = Number(input.history_count) || 0;

const pending = {
  id: id,
  timestamp: $now.toISO(),
  customer_phone: input.customer_phone,
  customer_name: input.customer_name || '',
  customer_message: input.user_message,
  conversation_history: input.conversation_history || '',
  history_count: hc,
  messages: messages,
  draft_text: messages.join('\n\n'),
  messages_sent_count: 0,
  notes: input.notes,
  telegram_message_id: null,
  telegram_chat_id: 5532831477,
  status: 'pending',
  break_condition: input.break_condition || { hit: false },
  is_lead: !!input.is_lead,
  is_payment: !!paymentMessage,   // Nomod: skip the FR-5 improver
  should_send_file: !!input.should_send_file,
  file_key: input.file_key || '',
  file_description: input.file_description || ''
};
// Supersede prior pending draft for the same customer. Operator's
// mental model is 'one active card per customer' — if the customer
// messaged again after debounce window expired (60s+), we created a
// new draft, so the OLD draft is stale. Mark it superseded, surface
// its message_id so downstream Notify Superseded Prior can edit the
// old Telegram card. SKIP drafts in operator-action-in-progress
// states (awaiting_edit/awaiting_amount/link_sent/sent/skipped/
// superseded) to avoid losing typed feedback or duplicating action.
let superseded_prior = null;
// Widened (operator: 'max 1 active card per customer'): also
// supersede 'sent' / 'link_sent' drafts. Old cards get a
// '↩️ continued in new card' marker so operator's screen has
// only ONE active card per customer at a time. Skip the
// operator-in-progress states ('awaiting_edit',
// 'awaiting_amount') so typed feedback doesn't vanish.
const SUPERSEDABLE_STATES = ['pending', 'sent', 'link_sent', 'skipped'];
for (const e of data.pendingQueue) {
  if (e && e.customer_phone === pending.customer_phone
      && e.id !== pending.id
      && SUPERSEDABLE_STATES.includes(e.status)) {
    e.status = 'superseded';
    superseded_prior = {
      draft_id: e.id,
      telegram_message_id: e.telegram_message_id || null,
      telegram_chat_id: e.telegram_chat_id || 5532831477,
      original_draft_text: e.draft_text || '',
      original_customer_message: e.customer_message || ''
    };
    break;  // only one prior at most
  }
}
data.pendingQueue.push(pending);

const preview = messages.length === 1
  ? messages[0]
  : messages.map((m, i) => (i + 1) + '. ' + m).join('\n');
const draftHeader = messages.length === 1 ? '💬 DRAFT:' : ('💬 DRAFT (' + messages.length + ' messages):');
const histLine = hc > 0
  ? ('📜 History: ' + hc + ' prior message' + (hc === 1 ? '' : 's'))
  : '📜 First contact';

let lines;
if (input.is_lead) {
  lines = ['🆕 NEW LEAD — outbound first contact', '📞 ' + pending.customer_phone, '', 'Lead brief (from you):', '"' + pending.customer_message + '"', '', '---', draftHeader, preview, '', '📝 Notes: ' + pending.notes];
} else {
  // Show name in the 'from' line when we have one — @lid hash is
// not human-readable. Falls back to customer_phone (the @lid id
// or @c.us number) when no name resolved.
const _displayName = (pending.customer_name && pending.customer_name.trim()) || pending.customer_phone;
lines = ['📩 from ' + _displayName];
  if (customerHeader) {
    lines.push(customerHeader);
  } else {
    if (pending.customer_name) lines.push('👤 ' + pending.customer_name);
    lines.push(histLine);
  }
  lines.push('', 'They said:', '"' + pending.customer_message + '"', '', '---', draftHeader, preview, '', '📝 Notes: ' + pending.notes);
}

if (paymentHeader) lines = [paymentHeader].concat(lines);

if (pending && pending.should_send_file && pending.file_key) {
    (lines || []).push('📎 Suggested file: ' + pending.file_key);
  }
  const reply_markup = {
  inline_keyboard: [
    [{ text: '✅ Send', callback_data: 'send:' + id }, { text: '✏️ Edit', callback_data: 'edit:' + id }],
    [{ text: '🔁 Regen', callback_data: 'regen:' + id }, { text: '❌ Skip', callback_data: 'skip:' + id }],
    [{ text: '🤖 Auto', callback_data: 'auto:' + id },
     { text: '💳 Send Link', callback_data: 'paylink:' + id }],
      ...((pending && pending.should_send_file && pending.file_key) ? [[{ text: '📎 Send File ('+(pending.file_key)+')', callback_data: 'file:' + id }]] : [])
  ]
};
return { json: { telegram_payload: { chat_id: 5532831477, text: lines.join('\n'), reply_markup: reply_markup }, draft_id: id, draft: pending, superseded_prior: superseded_prior } };

// Save Telegram message_id back to the pending draft for later editing
const tgResponse = $input.item.json;
const messageId = tgResponse.result?.message_id;
const draftId = $('Queue & Format').item.json.draft_id;

const data = $getWorkflowStaticData('global');
const entry = (data.pendingQueue || []).find(d => d.id === draftId);
if (entry && messageId) {
  entry.telegram_message_id = messageId;
}
return { json: { draft_id: draftId, telegram_message_id: messageId, ok: tgResponse.ok } };

// Verify the update is from Zayn (admin)
const body = $input.item.json.body || {};
const adminId = 5532831477;

const fromId = body.callback_query?.from?.id || body.message?.from?.id;

if (fromId !== adminId) {
  // Silently drop — return empty
  return null;
}

// Tag the update type for downstream routing
let updateType = 'unknown';
if (body.callback_query) updateType = 'callback_query';
else if (body.message?.text) updateType = 'message';

return {
  json: {
    update_type: updateType,
    callback_query: body.callback_query || null,
    message: body.message || null,
    raw: body
  }
};

// Parse callback_data + resolve the draft from Redis (the SOLE
// store as of the 2026-05-28 migration — staticData.pendingQueue
// removed). This node sits downstream of 'Redis Draft Lookup', so
// $json is the lookup result (a /queue?action=get response).
const cq = $('Route Update Type').item.json.callback_query;
const data = (cq && cq.data) || '';
const parts = data.split(':');
const action = parts[0] || '';
const second = parts[1] || '';
const third  = parts[2] || '';

const pipeline = (action === 'nudge' || action === 'snz' || action === 'inf' || action === 'disregard' || action === 'disregard_force');

let draft = null;
if (!pipeline) {
  try {
    if ($json && $json.found && $json.draft) draft = $json.draft;
  } catch (e) { draft = null; }
}

return {
  json: {
    action: action,
    draft_id: pipeline ? null : second,
    customer_id: pipeline ? second : (draft ? draft.customer_phone : null),
    snooze_duration: (action === 'snz') ? third : null,
    callback_query_id: cq && cq.id,
    chat_id: cq && cq.message && cq.message.chat.id,
    message_id: cq && cq.message && cq.message.message_id,
    draft: draft,
    draft_source: draft ? 'redis' : 'none',
    draft_found: !!draft
      || (action || '').indexOf('feedback_') === 0
      || pipeline
  }
};

