// R3: mark draft sent + record how many messages went out
const draftId = $('Parse Callback').item.json.draft_id;
const data = $getWorkflowStaticData('global');
const entry = (data.pendingQueue || []).find(d => d.id === draftId);
if (entry) {
  entry.status = 'sent';
  entry.messages_sent_count = Array.isArray(entry.messages) ? entry.messages.length : 1;
}
return { json: { ok: true, status: 'sent', draft_id: draftId, messages_sent_count: entry ? entry.messages_sent_count : 0 } };

