parameters.jsCode:
const draftId = $('Parse Callback').item.json.draft_id;
const data = $getWorkflowStaticData('global');
const entry = (data.pendingQueue || []).find(d => d.id === draftId);
if (entry) entry.status = 'skipped';
return { json: { ok: true, status: 'skipped', draft_id: draftId } };

// R4: only one draft may await an edit at a time.
// Redis-migration 2026-05-28: write status to Redis (bridge
// mark sets the awaiting_edit singleton via _draft_update) so
// Process Text Reply's Redis 'awaiting' lookup finds it.
// Previously this only mutated staticData -> after the read
// migration, edit feedback silently fell through.
const pc = $('Parse Callback').item.json;
const draftId = pc.draft_id;
const pcDraft = pc.draft || {};
const adminChatId = pc.chat_id || 5532831477;
const _http = this.helpers.httpRequest.bind(this.helpers);
async function bq(action, extra) {
  try {
    return await _http({ method: 'POST',
      url: 'http://172.18.0.1:8788/queue',
      headers: { 'Content-Type': 'application/json',
        'X-Bridge-Token': $env.BRIDGE_TOKEN || '' },
      body: Object.assign({ action: action }, extra || {}),
      json: true, timeout: 8000 });
  } catch (e) { return null; }
}
// A previous draft still holds the awaiting_edit lock? Single
// operator: tapping Edit on a NEW draft means the old edit was
// abandoned, so STEAL the lock instead of blocking. Incident
// 2026-05-28: a stale lock blocked the new edit (blocked=true) and
// the operator's typed edit then leaked to /assist as a nudge to a
// DIFFERENT customer (wrong-number send). Release the old lock
// first so this draft's lock is the only one.
const cur = await bq('awaiting', { status: 'awaiting_edit', chat_id: adminChatId });
if (cur && cur.found && cur.draft && cur.draft.id !== draftId) {
  await bq('mark', { draft_id: cur.draft.id, status: 'pending' });
}
// set awaiting_edit in Redis (singleton written by bridge).
// RETRY: the lock MUST land or the operator's next message won't
// route to refine (it would hit /assist). 3 tries covers a
// transient bridge hiccup under load (2026-05-28: marks were
// silently failing during high-volume bursts).
let _mk = null;
for (let _i = 0; _i < 3 && !(_mk && _mk.ok); _i++) {
  _mk = await bq('mark', { draft_id: draftId, status: 'awaiting_edit' });
}
return { json: {
  blocked: false,
  draft_id: draftId,
  customer_phone: pcDraft.customer_phone || 'unknown',
  original_draft: (pcDraft.messages && pcDraft.messages[0]) || pcDraft.draft_text || 'unknown'
} };

