// Parse regen response → new content + a fully-rendered card.
// Redis-migration 2026-05-28: no longer relies on staticData for
// the authoritative draft. Customer context comes from the Redis
// draft (via Parse Callback); the new content + card are committed
// ATOMICALLY by the downstream 'Regen Commit (Classic)' node
// (card edit + Redis write in one bridge call), so what the
// operator sees == what Send fans. Bug 2026-05-28: classic regen
// wrote only staticData, so Send pushed the pre-regen text.
const response = $input.item.json;
let raw = '';
try { raw = response.content[0].text; } catch (e) {
  return { json: { error: 'Empty Claude response on regen', raw: JSON.stringify(response) } };
}
let cleaned = raw.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
  if (!Array.isArray(parsed.messages) || !parsed.messages.length) throw new Error('messages missing');
} catch (e) {
  parsed = { messages: [raw], notes_for_zayn: '(parse fail: ' + e.message + ')' };
}
const msgs = parsed.messages.slice(0, 4).map(m => String(m));
const draftId = $('Build Regen Prompt').item.json.draft_id;

// Authoritative customer context = the Redis draft resolved by
// Parse Callback. Fall back to staticData only if it's absent.
const pc = $('Parse Callback').item.json || {};
const d  = pc.draft || {};
let cust = { phone: d.customer_phone, name: d.customer_name, message: d.customer_message };
if (!cust.phone) {
  const data = $getWorkflowStaticData('global');
  const entry = (data.pendingQueue || []).find(x => x.id === draftId);
  if (entry) cust = { phone: entry.customer_phone, name: entry.customer_name, message: entry.customer_message };
}

const new_draft_text = msgs.join('\n\n');
const preview = msgs.length === 1 ? msgs[0] : msgs.map((m, i) => (i + 1) + '. ' + m).join('\n');
const new_notes = parsed.notes_for_zayn || '(no notes)';

const card_text = '\ud83d\udce9 [REGEN] from ' + (cust.phone || '?') +
  '\nName: ' + (cust.name || '(unknown)') +
  '\n\nThey said:\n"' + (cust.message || '') + '"' +
  '\n\n---\n\ud83d\udcac NEW DRAFT:\n' + preview +
  '\n\n\ud83d\udcdd Notes: ' + new_notes;
const reply_markup = { inline_keyboard: [
  [{ text: '\u2705 Send', callback_data: 'send:' + draftId }, { text: '\u270f\ufe0f Edit', callback_data: 'edit:' + draftId }],
  [{ text: '\ud83d\udd01 Regen', callback_data: 'regen:' + draftId }, { text: '\u274c Skip', callback_data: 'skip:' + draftId }],
  [{ text: '\ud83e\udd16 Auto', callback_data: 'auto:' + draftId }, { text: '\ud83d\udcb3 Send Link', callback_data: 'paylink:' + draftId }]
]};

return { json: {
  draft_id: draftId,
  new_messages: msgs,
  new_draft_text: new_draft_text,
  new_preview: preview,
  new_notes: new_notes,
  customer_phone: cust.phone || 'unknown',
  customer_name: cust.name || '',
  customer_message: cust.message || '',
  card: { chat_id: pc.chat_id, message_id: pc.message_id, text: card_text, reply_markup: reply_markup },
  should_send_file: !!(parsed && parsed.should_send_file === true),
  file_key: (parsed && typeof parsed.file_key === 'string') ? parsed.file_key.trim() : '',
  file_description: (parsed && typeof parsed.file_description === 'string') ? parsed.file_description.trim() : '',
} };

// route an admin Telegram message: /lead, /send, edit-feedback, reply, or ack
const msg = $input.item.json.message || {};
const text = (msg.text || '').trim();
const adminChatId = (msg.chat && msg.chat.id) ? msg.chat.id : 5532831477;
// Redis-migration 2026-05-28: bridge lookups replace staticData
// queue scans. _http is bound so it works inside this node.
const _http = this.helpers.httpRequest.bind(this.helpers);
async function bq(action, extra) {
  try {
    return await _http({
      method: 'POST',
      url: 'http://172.18.0.1:8788/queue',
      headers: { 'Content-Type': 'application/json',
        'X-Bridge-Token': $env.BRIDGE_TOKEN || '' },
      body: Object.assign({ action: action }, extra || {}),
      json: true, timeout: 8000,
    });
  } catch (e) { return null; }
}

// (C) /lead <free-form> -> create an outbound first-contact draft (FR-2)
if (text.toLowerCase().indexOf('/lead') === 0) {
  const leadText = text.slice(5).trim();
  const cand = leadText.match(/[+\d][\d\s().\-]{7,}\d/g) || [];
  let phone = '';
  for (const c of cand) {
    const d = c.replace(/[^\d]/g, '');
    if (d.length >= 9 && d.length > phone.length) phone = d;
  }
  if (!phone) {
    return { json: { action: 'ack', admin_chat_id: adminChatId,
      ack_text: "⚠️ Couldn't find a phone number in that lead. Try:  /lead <name> <phone> <details>" } };
  }
  let norm = phone.replace(/^00/, '');
  if (norm.length === 10 && norm[0] === '0') norm = '971' + norm.slice(1);
  else if (norm.length === 9 && norm[0] === '5') norm = '971' + norm;
  return { json: { action: 'new_lead', lead_phone: norm + '@c.us',
    lead_text: leadText, admin_chat_id: adminChatId } };
}

// (B) /send <chatId> <message>
if (text.toLowerCase().indexOf('/send ') === 0) {
  const rest = text.slice(6).trim();
  const sp = rest.indexOf(' ');
  if (sp < 1) {
    return { json: { action: 'ack', admin_chat_id: adminChatId,
      ack_text: 'Usage:  /send <chatId> <message>' } };
  }
  return { json: { action: 'send_to_customer', origin: 'slash',
    target_chatId: rest.slice(0, sp).trim(), final_text: rest.slice(sp + 1).trim(),
    admin_chat_id: adminChatId } };
}

// (E) /auto, /manual — switch a conversation's autonomous mode (FR-4)
{
  const low = text.toLowerCase();
  if (low === '/auto' || low === '/manual' || low === '/manual all') {
    let d2 = null;
    const r2 = msg.reply_to_message;
    if (r2 && r2.message_id) {
      const _r = await bq('get-by-tgmsg', { message_id: r2.message_id });
      d2 = (_r && _r.found) ? _r.draft : null;
    }
    if (low === '/auto') {
      if (!d2) {
        return { json: { action: 'ack', admin_chat_id: adminChatId,
          ack_text: '⚠️ reply to a customer draft card with /auto to hand that conversation to autonomous mode.' } };
      }
      return { json: { action: 'mode_cmd', mode_target: d2.customer_phone,
        mode: 'autonomous', admin_chat_id: adminChatId } };
    }
    if (low === '/manual all' || !d2) {
      return { json: { action: 'mode_cmd', mode_target: '__ALL__',
        mode: 'approval', admin_chat_id: adminChatId } };
    }
    return { json: { action: 'mode_cmd', mode_target: d2.customer_phone,
      mode: 'approval', admin_chat_id: adminChatId } };
  }
}

// (F) /caps — report autonomous-mode safety-cap status (BUG-2)
if (text.toLowerCase() === '/caps') {
  return { json: { action: 'caps_cmd', admin_chat_id: adminChatId } };
}

// (PRF) /refresh <name-or-phone-or-@lid> — re-extract customer_facts
// via WAHA history.
// Arg detection order: @lid id (contains '@') > phone (7+ digits, with
// optional + sign / spaces / hyphens) > name (anything else).
{
  const lo = text.toLowerCase();
  if (lo === '/refresh' || lo.indexOf('/refresh ') === 0) {
    const arg = text.slice(8).trim();
    if (!arg) {
      return { json: { action: 'ack', admin_chat_id: adminChatId,
        ack_text: 'Usage:  /refresh <name | phone | @lid customer_id>' } };
    }
    const isId = arg.indexOf('@') >= 0;
    const phoneDigits = arg.replace(/[\s\-()+]/g, '');
    const isPhone = !isId && /^\d{7,}$/.test(phoneDigits);
    const kind = isId ? 'customer_id' : (isPhone ? 'phone' : 'name');
    const value = isPhone ? phoneDigits : arg;
    return { json: { action: 'refresh_cmd', refresh_query: value,
      refresh_query_kind: kind, admin_chat_id: adminChatId } };
  }
}

// (PR) /review [filter] — Pipeline Review report (Step 5 of pipeline-review)
{
  const lo = text.toLowerCase();
  if (lo === '/review' || lo.indexOf('/review ') === 0) {
    const arg = text.slice(7).trim().toLowerCase();
    const allowed = ['all','hot','warm','cold'];
    const filt = allowed.indexOf(arg) >= 0 ? arg : 'all';
    return { json: { action: 'review_cmd', filter: filt,
      admin_chat_id: adminChatId } };
  }
}

// (PI) /info <name-or-phone> — single-lead context dump
{
  const lo = text.toLowerCase();
  if (lo === '/info' || lo.indexOf('/info ') === 0) {
    const arg = text.slice(5).trim();
    if (!arg) {
      return { json: { action: 'ack', admin_chat_id: adminChatId,
        ack_text: 'Usage:  /info <name or phone>' } };
    }
    // @lid customer_ids contain '@'; everything else is treated as a name.
    const isId = arg.indexOf('@') >= 0;
    return { json: { action: 'info_cmd', info_query: arg,
      info_query_kind: isId ? 'customer_id' : 'name',
      admin_chat_id: adminChatId } };
  }
}

// (PL) /label <name-or-phone> <LABEL> — manual label override
{
  const lo = text.toLowerCase();
  if (lo === '/label' || lo.indexOf('/label ') === 0) {
    const parts = text.slice(7).trim().split(/\s+/);
    if (parts.length < 2) {
      return { json: { action: 'ack', admin_chat_id: adminChatId,
        ack_text: 'Usage:  /label <name or phone> <LABEL>\n'
          + 'LABELS: NEW, WARM, HOT, NEEDS_ATTENTION, COLD,\n'
          + '        PAUSED_SPAM, PAUSED_B2B, PAUSED_PERSONAL' } };
    }
    const label = parts[parts.length - 1].toUpperCase();
    const who = parts.slice(0, -1).join(' ');
    const isId = who.indexOf('@') >= 0;
    return { json: { action: 'label_cmd', label_query: who,
      label_query_kind: isId ? 'customer_id' : 'name',
      label_value: label, admin_chat_id: adminChatId } };
  }
}

// (PS) /snooze <name-or-phone> <dur> — snooze a customer (no label change)
{
  const lo = text.toLowerCase();
  if (lo === '/snooze' || lo.indexOf('/snooze ') === 0) {
    const parts = text.slice(8).trim().split(/\s+/);
    if (parts.length < 2) {
      return { json: { action: 'ack', admin_chat_id: adminChatId,
        ack_text: 'Usage:  /snooze <name or phone> <duration>\n'
          + 'examples:  /snooze Mark 4h    /snooze +971... 2d' } };
    }
    const duration = parts[parts.length - 1].toLowerCase();
    const who = parts.slice(0, -1).join(' ');
    const isId = who.indexOf('@') >= 0;
    return { json: { action: 'snooze_cmd', snooze_query: who,
      snooze_query_kind: isId ? 'customer_id' : 'name',
      snooze_duration: duration, admin_chat_id: adminChatId } };
  }
}

// (G) /feedback <text> — operator behavioural feedback (classify +
//     confirm + store in customer_notes / behavior_rules)
{
  const lo = text.toLowerCase();
  if (lo === '/feedback' || lo.indexOf('/feedback ') === 0) {
    const fb = text.slice(9).trim();
    if (!fb) {
      return { json: { action: 'ack', admin_chat_id: adminChatId,
        ack_text: 'Usage:  /feedback <text>\n'
          + 'examples:\n'
          + '  /feedback never offer phone calls\n'
          + '  /feedback Mark booked Aurora last March, mention it\n'
          + '  /feedback offer fine dining first to family groups'
      } };
    }
    return { json: { action: 'feedback_cmd', feedback_text: fb,
      admin_chat_id: adminChatId } };
  }
}

// (D) /rules, /approverule <id>, /discardrule <id> — rule review (FR-5)
{
  const low = text.toLowerCase();
  if (low === '/rules' || low.indexOf('/rules ') === 0) {
    return { json: { action: 'rules_cmd', rules_action: 'list', rule_id: null,
      admin_chat_id: adminChatId } };
  }
  if (low.indexOf('/approverule ') === 0 || low.indexOf('/discardrule ') === 0) {
    const isApprove = low.indexOf('/approverule ') === 0;
    const rid = (text.split(/\s+/)[1] || '').trim();
    if (!/^\d+$/.test(rid)) {
      return { json: { action: 'ack', admin_chat_id: adminChatId,
        ack_text: 'Usage:  ' + (isApprove ? '/approverule' : '/discardrule')
          + ' <rule id number>' } };
    }
    return { json: { action: 'rules_cmd',
      rules_action: isApprove ? 'activate' : 'discard', rid_text: rid,
      rule_id: rid, admin_chat_id: adminChatId } };
  }
}

// (paylink-amount) a draft is awaiting a payment amount — operator
// hit [💳 Send Link] on a draft that had no payment_amount, so the
// workflow prompted for one. The next text reply IS the amount.
{
  const _aa = await bq('awaiting', { status: 'awaiting_amount', chat_id: adminChatId });
  const await_amt = (_aa && _aa.found) ? _aa.draft : null;
  if (await_amt && text) {
    // Parse: digits, optional 'k' suffix (5k -> 5000), commas + decimals ok
    const m = text.trim().match(/^([\d,]+(?:\.\d+)?)(k)?$/i);
    if (!m) {
      return { json: { action: 'ack', admin_chat_id: adminChatId,
        ack_text: '⚠️ Amount not recognised. Type a plain AED number (e.g. 3000 or 3k).' } };
    }
    let amt = parseFloat(m[1].replace(/,/g, ''));
    if (m[2]) amt *= 1000;
    if (!(amt > 0)) {
      return { json: { action: 'ack', admin_chat_id: adminChatId,
        ack_text: '⚠️ Amount must be positive.' } };
    }
    await bq('mark', { draft_id: await_amt.id, status: 'pending' });  // release lock in Redis
    return { json: { action: 'paylink_amount', draft_id: await_amt.id,
      amount: amt, admin_chat_id: adminChatId } };
  }
}

// (edit) a draft is awaiting feedback -> refine it, do NOT send (FR-1)
const _ae = await bq('awaiting', { status: 'awaiting_edit', chat_id: adminChatId });
const awaiting = (_ae && _ae.found) ? _ae.draft : null;
if (awaiting && text) {
  await bq('mark', { draft_id: awaiting.id, status: 'pending' });  // release the edit lock in Redis
  return { json: { action: 'refine', draft_id: awaiting.id, feedback: text,
    admin_chat_id: adminChatId } };
}

// (A) reply to a draft card — DEFAULT: feedback to Claude (refine). Only an
//     explicit "send this: X" sends X verbatim; "ask this: X" -> refine to ask X.
const r = msg.reply_to_message;
if (r && r.message_id) {
  // Resolve the replied-to card to its draft (newest-match: telegram
  // message_ids collide across bot/session resets).
  const _rr = await bq('get-by-tgmsg', { message_id: r.message_id });
  let d = (_rr && _rr.found) ? _rr.draft : null;
  // Fallback: the replied-to message may not be the card itself, or
  // the card's draft may have expired. If an awaiting_edit lock is
  // set for this chat (operator tapped Edit), refine THAT draft.
  if (!d) {
    const _ae2 = await bq('awaiting', { status: 'awaiting_edit', chat_id: adminChatId });
    d = (_ae2 && _ae2.found) ? _ae2.draft : null;
  }
  if (d && text) {
    const lo = text.toLowerCase();
    if (lo.indexOf('send this:') === 0) {
      return { json: { action: 'send_to_customer', origin: 'reply',
        target_chatId: d.customer_phone, final_text: text.slice(10).trim(),
        draft_id: d.id, admin_chat_id: adminChatId } };
    }
    let fb = text;
    if (lo.indexOf('ask this:') === 0) {
      fb = 'Ask the customer: ' + text.slice(9).trim();
    }
    return { json: { action: 'refine', draft_id: d.id, feedback: fb,
      admin_chat_id: adminChatId } };
  }
  // A REPLY must NEVER fall through to /assist — that could send a
  // nudge to a wrong fuzzy-matched customer (wrong-number incident
  // 2026-05-28). If we can't map the reply to a live draft, say so.
  return { json: { action: 'ack', admin_chat_id: adminChatId,
    ack_text: "\u26a0\ufe0f Couldn't match that reply to a live "
      + "draft card (it may have already been sent or expired). "
      + "Tap \u270f\ufe0f Edit on the card you want to change, "
      + "then type your edit." } };
}

// (Z) FALLBACK — non-command, non-reply free-text from operator -> /assist endpoint for natural-language routing
//     (status queries, draft nudges, paylink creation, customer search). Empty text still acks.
if (!text || !text.trim()) {
  return { json: { action: 'ack', admin_chat_id: adminChatId,
    ack_text: '⚠️ Empty message.' } };
}
return { json: { action: 'assist_query', query_text: text, admin_chat_id: adminChatId } };

// R1: build a failure alert for Zayn from a node error-output item
const j = $input.item.json || {};
const err = j.error || {};
let msg;
try { msg = err.message || err.description || (typeof err === 'string' ? err : '') || JSON.stringify(err); }
catch (e) { msg = 'unrecognised error'; }
let phone = j.customerPhone || j.customer_phone || '';
try { if (!phone && j.draft) phone = j.draft.customer_phone || ''; } catch (e) {}
const text = '\u26a0\ufe0f Phase 1B \u2014 a step failed\n\n'
  + 'The workflow caught the error instead of dying silently.\n\n'
  + 'Error: ' + (msg || 'unknown') + '\n'
  + (phone ? 'Customer: ' + phone + '\n' : '')
  + '\nNothing was force-sent. Open N8N \u2192 Executions to find the failed '
  + 'node and check the pending queue, then handle it manually.';
return { json: { chat_id: 5532831477, alert_text: text } };

