parameters.jsCode:
// R3: fan a draft's messages[] into one item per message.
// Race-safe: first call to bridge /queue?action=claim-send wins.
// Concurrent send taps (operator double-click, Telegram retry,
// or n8n queue replay) all hit the same Redis SET NX key — only
// the winner gets ok=true and proceeds.
// Production bug 2026-05-27: operator's [Send] tap occasionally
// produced 2 WAHA sendText calls to same customer within ~2s.
const draft = $('Parse Callback').first().json.draft;

if (!draft || !draft.id) return [];

// 1. atomic send-claim via bridge. Wins-or-skips.
let claimed = false;
try {
  const claimResp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://172.18.0.1:8788/queue',
    headers: {
      'Content-Type': 'application/json',
      'X-Bridge-Token': $env.BRIDGE_TOKEN || '',
    },
    body: { action: 'claim-send', draft_id: draft.id, ttl: 60 },
    json: true,
    timeout: 6000,
  });
  claimed = !!(claimResp && claimResp.ok);
} catch (e) {
  // If the claim endpoint is unreachable, fall back to the
  // pre-existing messages_sent_count check below. Better to
  // proceed (single send, no message lost) than block.
  claimed = true;
}
if (!claimed) {
  // Another concurrent send already won the claim. Bail.
  return [];
}

// 2. Existing belt-and-braces guard: if Mark Sent has already
// run for this draft, don't re-fire. The claim above closes
// the race window between read + send; this check catches the
// rare case where claim TTL expired but Mark Sent persisted.
if (draft && (draft.messages_sent_count || 0) > 0) {
  return [];
}

const msgs = (draft && Array.isArray(draft.messages) && draft.messages.length)
  ? draft.messages
  : [ (draft && draft.draft_text) || '(empty draft)' ];
return msgs.map((m, i) => ({
  json: { chatId: draft.customer_phone, text: String(m), seq: i + 1, total: msgs.length, draft_id: draft.id }
}));

// #1 + FR-3: build conversation_history from WAHA; use the debounced message set
const wh = $('WAHA Webhook').first().json.body.payload;
const fc = $('Flush Check').first().json;
const chatId = wh.from;
const excludeIds = new Set((fc.bufferedIds && fc.bufferedIds.length) ? fc.bufferedIds : [wh.id]);
const newestMessage = (fc.combinedMessage && String(fc.combinedMessage).trim())
  ? fc.combinedMessage
  : (wh.body || '');

let msgs = [];
for (const it of $input.all()) {
  const j = it.json;
  if (j && typeof j.body === 'string' && typeof j.fromMe === 'boolean' && j.timestamp) {
    msgs.push(j);
  } else if (Array.isArray(j)) {
    for (const m of j) { if (m && typeof m.body === 'string') msgs.push(m); }
  }
}
msgs = msgs
  .filter(m => m.body && String(m.body).trim() && !excludeIds.has(m.id))
  .sort((a, b) => (a.timestamp || 0) - (b.timestamp || 0));

const now = Math.floor(Date.now() / 1000);
function ago(ts) {
  const s = Math.max(0, now - (ts || now));
  if (s < 90) return 'just now';
  if (s < 5400) return Math.round(s / 60) + 'm ago';
  if (s < 129600) return Math.round(s / 3600) + 'h ago';
  return Math.round(s / 86400) + 'd ago';
}

let history;
if (msgs.length === 0) {
  history = 'First contact, no prior messages.';
} else {
  history = msgs.slice(-15).map(function (m) {
    const who = m.fromMe ? 'Dubriani' : 'Customer';
    const body = String(m.body).replace(/\s+/g, ' ').trim();
    return who + ' (' + ago(m.timestamp) + '): "' + body + '"';
  }).join('\n');
}

return [{ json: {
  conversationHistory: history,
  historyCount: msgs.length,
  customerChatId: chatId,
  customerName: wh.notifyName || wh.pushName || '',
  userMessage: newestMessage
} }];

// FR-1: gather the draft + Zayn's feedback for a refine redraft.
// Redis-migration 2026-05-28: fetch the draft from Redis (bridge
// get) instead of staticData, so refine works even when the
// draft isn't in this workflow's staticData (e.g. nudge drafts,
// or after the read-migration removed staticData reconciliation).
const inp = $('Process Text Reply').item.json;
const draftId = inp.draft_id;
const feedback = inp.feedback || '';
const _http = this.helpers.httpRequest.bind(this.helpers);
let draft = null;
try {
  const r = await _http({ method: 'POST',
    url: 'http://172.18.0.1:8788/queue',
    headers: { 'Content-Type': 'application/json',
      'X-Bridge-Token': $env.BRIDGE_TOKEN || '' },
    body: { action: 'get', draft_id: draftId },
    json: true, timeout: 8000 });
  if (r && r.found && r.draft) draft = r.draft;
} catch (e) { draft = null; }
if (!draft) {
  return { json: { error: 'Draft not found for refine', draft_id: draftId } };
}
return { json: {
  systemPrompt: '',
  userMessage: draft.customer_message || '(no customer message)',
  conversationHistory: draft.conversation_history || 'First contact, no prior messages.',
  historyCount: draft.history_count || 0,
  customerPhone: draft.customer_phone,
  customerName: draft.customer_name || '',
  regenHint: 'Zayn reviewed the previous draft and gave this feedback: "' + feedback
    + '". The previous draft was: "' + draft.draft_text
    + '". Rewrite the reply to incorporate Zayn\'s feedback, staying within all hard rules and the conversation history above.',
  draft_id: draftId,
  telegram_message_id: draft.telegram_message_id,
  admin_chat_id: inp.admin_chat_id || 5532831477
} };

