// FR-1: parse the refine response, update the draft, re-render its card
const response = $input.item.json;
let raw = '';
try { raw = response.content[0].text; } catch (e) {
  return { json: { error: 'Empty Claude response on refine', raw: JSON.stringify(response) } };
}
let cleaned = raw.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
  if (!Array.isArray(parsed.messages) || !parsed.messages.length) throw new Error('messages missing');
} catch (e) {
  parsed = { messages: [raw], notes_for_zayn: '(parse fail: ' + e.message + ')' };
}
const msgs = parsed.messages.slice(0, 4).map(m => String(m));
const bp = $('Build Refine Prompt').item.json;
const draftId = bp.draft_id;
const data = $getWorkflowStaticData('global');
const entry = (data.pendingQueue || []).find(d => d.id === draftId);
if (entry) {
  entry.messages = msgs;
  entry.draft_text = msgs.join('\n\n');
  entry.notes = parsed.notes_for_zayn || entry.notes;
  entry.messages_sent_count = 0;
  entry.status = 'pending';
}
const preview = msgs.length === 1 ? msgs[0] : msgs.map((m, i) => (i + 1) + '. ' + m).join('\n');
return { json: {
  draft_id: draftId,
  // FIX 2026-05-27: include messages + draft_text so the downstream
  // 'Sync Refine To Redis' node can POST them to /queue update,
  // keeping Redis aligned with staticData. Without this, Send button
  // reads stale Redis content and sends the pre-refine message.
  messages: msgs,
  draft_text: msgs.join('\n\n'),
  notes: parsed.notes_for_zayn || (entry ? entry.notes : ''),
  new_preview: preview,
  new_notes: parsed.notes_for_zayn || '(no notes)',
  customer_phone: entry ? entry.customer_phone : 'unknown',
  customer_name: entry ? entry.customer_name : '',
  customer_message: entry ? entry.customer_message : '',
  telegram_message_id: bp.telegram_message_id,
  admin_chat_id: bp.admin_chat_id,
  // Atomic refine commit (2026-05-28): card + Redis written
  // together by 'Refine Commit' (regen-commit) so an exec crash
  // can't leave Redis ahead of the card (sent != shown).
  card: {
    chat_id: bp.admin_chat_id,
    message_id: bp.telegram_message_id,
    text: '\ud83d\udce9 [REFINED] from ' + (entry ? entry.customer_phone : 'unknown')
      + '\nName: ' + ((entry && entry.customer_name) || '(unknown)')
      + '\n\nThey said:\n"' + ((entry && entry.customer_message) || '') + '"'
      + '\n\n---\n\ud83d\udcac NEW DRAFT:\n' + preview
      + '\n\n\ud83d\udcdd Notes: ' + (parsed.notes_for_zayn || '(no notes)'),
    reply_markup: { inline_keyboard: [
      [{ text: '\u2705 Send', callback_data: 'send:' + draftId }, { text: '\u270f\ufe0f Edit', callback_data: 'edit:' + draftId }],
      [{ text: '\ud83d\udd01 Regen', callback_data: 'regen:' + draftId }, { text: '\u274c Skip', callback_data: 'skip:' + draftId }],
      [{ text: '\ud83e\udd16 Auto', callback_data: 'auto:' + draftId }, { text: '\ud83d\udcb3 Send Link', callback_data: 'paylink:' + draftId }]
    ] }
  },
  should_send_file: !!(parsed && parsed.should_send_file === true),
  file_key: (parsed && typeof parsed.file_key === 'string')
    ? parsed.file_key.trim() : '',
  file_description: (parsed && typeof parsed.file_description === 'string')
    ? parsed.file_description.trim() : '',
} };

// FR-2: gather the new lead for an outbound first-contact draft.
// Also pre-extract the customer name from common form-paste formats
// ('Name: <X>', 'Customer: <X>') — Hermes's chat-tuned name extractor
// misses these reliably, so we feed the regex hit as customer_name to
// /customer-facts and the bridge falls back to it when the LLM
// returns empty.
const inp = $('Process Text Reply').item.json;
const leadText = inp.lead_text || '';
let leadName = '';
const m = leadText.match(/(?:^|\n)\s*(?:name|customer)\s*[:;\s]\s*([A-Za-z][A-Za-z\s.'-]{1,40})/i);
if (m) leadName = m[1].trim().replace(/[\s,;:]+$/, '');
return { json: {
  systemPrompt: '',
  leadPhone: inp.lead_phone,
  leadText: leadText,
  leadName: leadName,
  adminChatId: inp.admin_chat_id || 5532831477
} };

