// FR-2: parse the lead opener draft from Claude
const response = $input.item.json;
const bp = $('Build Lead Prompt').item.json;
let raw = '';
try { raw = response.content[0].text; } catch (e) {
  return { json: {
    messages: ['(empty Claude response - check API node)'],
    notes: 'ERROR: could not extract text from Claude API response',
    parse_status: 'extract_failed',
    customer_phone: bp.leadPhone, customer_name: '', user_message: bp.leadText,
    conversation_history: '', history_count: 0, is_lead: true,
  should_send_file: !!(parsed && parsed.should_send_file === true),
  file_key: (parsed && typeof parsed.file_key === 'string')
    ? parsed.file_key.trim() : '',
  file_description: (parsed && typeof parsed.file_description === 'string')
    ? parsed.file_description.trim() : '',
  } };
}
let cleaned = raw.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
let parsed; let status = 'ok';
try {
  parsed = JSON.parse(cleaned);
  if (!Array.isArray(parsed.messages) || !parsed.messages.length) throw new Error('messages array missing or empty');
} catch (e) {
  parsed = { messages: [raw], notes_for_zayn: '(JSON parse failed - plain text. ' + e.message + ')' };
  status = 'fallback_plain_text';
}
const messages = parsed.messages.slice(0, 4).map(m => String(m));
return { json: {
  messages: messages,
  notes: parsed.notes_for_zayn || '(no notes)',
  parse_status: status,
  customer_phone: bp.leadPhone,
  customer_name: '',
  user_message: bp.leadText,
  conversation_history: '',
  history_count: 0,
  is_lead: true,
  should_send_file: !!(parsed && parsed.should_send_file === true),
  file_key: (parsed && typeof parsed.file_key === 'string')
    ? parsed.file_key.trim() : '',
  file_description: (parsed && typeof parsed.file_description === 'string')
    ? parsed.file_description.trim() : ''
} };

// FR-3 (BUG-1 fix): the bridge buffered this message in Redis and issued
// a token. staticData is NOT used — it cannot coordinate the concurrent
// executions that one-per-inbound-message spawns.
const wh = $('WAHA Webhook').item.json.body.payload;
const r = $('Debounce Buffer').item.json || {};
return { json: {
  phone: wh.from,
  token: r.token || '',
  degraded: !r.token        // bridge/Redis error -> Flush Check fails open
} };

// FR-3 (BUG-1 fix): proceed only if the bridge says this is the latest
// message for the customer. Redis-backed — see bridge /debounce.
const wh = $('WAHA Webhook').item.json.body.payload;
const bm = $('Buffer Message').item.json || {};
const r = $('Debounce Flush').item.json || {};
// Suppress this draft ONLY when buffering succeeded AND the bridge says a
// newer message superseded it. Every error path falls open (process), so
// a customer message is never silently dropped.
if (bm.degraded !== true && r.latest === false) {
  return [];
}
const combined = (r.combined && String(r.combined).trim())
  ? r.combined
  : (wh.body || '');
return [{ json: {
  phone: wh.from,
  combinedMessage: combined,
  bufferedIds: (Array.isArray(r.ids) && r.ids.length) ? r.ids : [wh.id],
  bufferedCount: r.count || 1
} }];

// FR-5: improve a draft only while it is still pending (unsent)
const sid = $('Save Telegram MsgID').item.json;
const draftId = sid.draft_id;
// BUG-3 fix: the improver now runs on autonomous drafts too — Push
// Improved Text writes the improved copy into the Redis autosend key so
// the auto-send dispatches it (was: skipped armed drafts).
const data = $getWorkflowStaticData('global');
const d = (data.pendingQueue || []).find(x => x.id === draftId);
if (d && d.is_payment === true) {
  // Nomod: payment drafts carry a deterministic booking block +
  // real Nomod link appended by Build Payment Message; the
  // improver doesn't know about them and would strip them.
  return [];
}
if (!d || d.status !== 'pending') {
  return [];   // sent / skipped / awaiting_edit / gone — nothing to improve
}
return [{ json: {
  draft_id: draftId,
  telegram_message_id: d.telegram_message_id,
  customer_name: d.customer_name || '',
  customer_id: d.customer_phone || '',
  incoming_message: d.customer_message || '',
  history: d.conversation_history || '',
  current_draft: d.draft_text || (Array.isArray(d.messages) ? d.messages.join('\n\n') : '')
} }];

// FR-5: apply Hermes's improvement to the pending draft + re-render the card
const resp = $input.item.json || {};
const cp = $('Check Pending').item.json;
const draftId = cp.draft_id;
const data = $getWorkflowStaticData('global');
const d = (data.pendingQueue || []).find(x => x.id === draftId);
// race guard: the operator may have acted during the ~18s Hermes call
if (!d || d.status !== 'pending') return [];
// Race guard: even if staticData says 'pending', Redis is the
// cross-execution source of truth. The Send-callback execution
// may have flipped the draft to 'sent' between our exec-start
// snapshot and now. If Redis says 'sent'/'skipped'/'link_sent',
// abort — don't re-edit the card AFTER it's been actioned.
try {
  const redisResp = $('Recheck Draft Status').item.json || {};
  const redisDraft = redisResp.draft || null;
  if (redisDraft && redisDraft.status && redisDraft.status !== 'pending') {
    return [];
  }
} catch (e) { /* fall through — staticData check is enough */ }
if (resp.ok !== true || resp.improved !== true) return [];
const msgs = (Array.isArray(resp.messages) && resp.messages.length)
  ? resp.messages.slice(0, 4).map(m => String(m)) : null;
if (!msgs) return [];
d.messages = msgs;
d.draft_text = msgs.join('\n\n');
d.improved_note = resp.note || '';
const preview = msgs.length === 1 ? msgs[0]
  : msgs.map((m, i) => (i + 1) + '. ' + m).join('\n');
const draftHeader = msgs.length === 1 ? '💬 DRAFT:'
  : ('💬 DRAFT (' + msgs.length + ' messages):');
const lines = [];
// Apply Improvement was stripping the rich customer header that
// Queue & Format adds (name / yachts / dates / party / msg#).
// Reuse the same Customer Facts header here so the operator sees
// consistent context before AND after the improver fires.
let customerHeader = '';
try { customerHeader = ($('Customer Facts').item.json || {}).customer_header || ''; }
catch (e) { customerHeader = ''; }
// Show name in the 'from' line when available; @lid hash is
// not human-readable.
const displayName = (d.customer_name && d.customer_name.trim()) || d.customer_phone;
if (d.is_lead) {
  lines.push('🆕 NEW LEAD — outbound first contact', '📞 ' + d.customer_phone,
             '', 'Lead brief (from you):', '"' + d.customer_message + '"');
} else {
  lines.push('📩 from ' + displayName);
  if (customerHeader) {
    lines.push(customerHeader);
  } else if (d.customer_name) {
    lines.push('👤 ' + d.customer_name);
  }
  lines.push('', 'They said:', '"' + d.customer_message + '"');
}
lines.push('', '---', '✨ improved by Hermes', draftHeader, preview,
           '', '📝 Notes: ' + (d.notes || ''));
if (d && d.should_send_file && d.file_key) {
    (lines || []).push('📎 Suggested file: ' + d.file_key);
  }
  const reply_markup = { inline_keyboard: [
  [{ text: '✅ Send', callback_data: 'send:' + draftId },
   { text: '✏️ Edit', callback_data: 'edit:' + draftId }],
  [{ text: '🔁 Regen', callback_data: 'regen:' + draftId },
   { text: '❌ Skip', callback_data: 'skip:' + draftId }],
  [{ text: '🤖 Auto', callback_data: 'auto:' + draftId },
     { text: '💳 Send Link', callback_data: 'paylink:' + draftId }],
      ...((d && d.should_send_file && d.file_key) ? [[{ text: '📎 Send File ('+(d.file_key)+')', callback_data: 'file:' + draftId }]] : [])
] };
return [{ json: {
  chat_id: d.telegram_chat_id || 5532831477,
  message_id: cp.telegram_message_id,
  text: lines.join('\n'),
  reply_markup: reply_markup,
  draft_id: draftId,
  improved_draft_text: d.draft_text,
  improved_messages: msgs
} }];

// FR-5 4.3b: assemble the /learn payload from the operator's Edit feedback
const ptr = $('Process Text Reply').item.json;
const draftId = ptr.draft_id;
const data = $getWorkflowStaticData('global');
const d = (data.pendingQueue || []).find(x => x.id === draftId) || {};
return [{ json: {
  feedback: ptr.feedback || '',
  draft_text: d.draft_text || '',
  customer_id: d.customer_phone || '',
  customer_name: d.customer_name || '',
  admin_chat_id: ptr.admin_chat_id || 5532831477
} }];

// FR-5 4.3b: notify the operator only when /learn actually captured a rule
const r = $input.item.json || {};
const adminChatId = $('Prep Learn').item.json.admin_chat_id || 5532831477;
if (!r.ok || !r.captured || !r.rule_text) {
  return [];   // one-off feedback, or learn errored — no notice
}
const txt = '📚 learned a possible rule from your edit:\n\n"' + r.rule_text + '"\n\n'
  + '(' + (r.scope || 'global') + ' rule · id ' + r.rule_id
  + ' · inactive until you approve)\n\n'
  + 'review all:  /rules\napprove this:  /approverule ' + r.rule_id;
return [{ json: { telegram_payload: { chat_id: adminChatId, text: txt } } }];

// FR-5 4.3b: format the bridge /rules response into a Telegram reply
const r = $input.item.json || {};
const adminChatId = $('Process Text Reply').item.json.admin_chat_id || 5532831477;
let txt;
if (r.ok && Array.isArray(r.pending)) {
  if (!r.pending.length) {
    txt = '📚 no behaviour rules pending review.';
  } else {
    txt = '📚 rules pending your approval (' + r.pending.length + '):\n\n'
      + r.pending.map(function (x) {
          return '• [' + x.id + '] (' + x.scope + ') ' + x.rule_text;
        }).join('\n\n')
      + '\n\napprove:  /approverule <id>\ndiscard:  /discardrule <id>';
  }
} else if (r.ok && r.action) {
  txt = r.action === 'activate'
    ? '✅ rule ' + r.rule_id + ' activated — it will now shape drafts.'
    : '🗑 rule ' + r.rule_id + ' discarded.';
} else {
  txt = '⚠️ rules service unavailable — try again shortly.'
    + (r.error ? '\n(' + r.error + ')' : '');
}
return [{ json: { telegram_payload: { chat_id: adminChatId, text: txt } } }];

// FR-4 4-B: confirm an autonomous-mode change to the operator
const r = $input.item.json || {};
const cmd = $('Process Text Reply').item.json;
const adminChatId = cmd.admin_chat_id || 5532831477;
let txt;
if (r.ok && cmd.mode_target === '__ALL__') {
  txt = '🛑 kill switch — every conversation is back to manual approval.';
} else if (r.ok && cmd.mode === 'autonomous') {
  txt = '🤖 autonomous mode ON for ' + (cmd.mode_target || 'this conversation')
    + '.\nclaude will draft and auto-send here — with the safety caps and a '
    + 'review window. reply /manual to a card from this customer to take it back.';
} else if (r.ok) {
  txt = '🙋 back to manual approval for '
    + (cmd.mode_target || 'this conversation') + '.';
} else {
  txt = '⚠️ could not change mode' + (r.error ? ': ' + r.error : '')
    + ' — try again.';
}
return [{ json: { telegram_payload: { chat_id: adminChatId, text: txt } } }];

