    + 'waiting for you to review and send.'
].join('\n');
return [{ json: {
  draft_id: sid.draft_id,
  customer_id: customer,
  break_hit: bc.hit === true,
  break_reason: reason,
  break_detail: detail,
  alert_text: alert_text
} }];

// Nomod minimal: build the payment WhatsApp message + operator card header
const pr = $('Parse Response').item.json || {};
let link = {};
try { link = $('Generate Payment Link').item.json || {}; } catch (e) { link = {}; }
const msgs = Array.isArray(pr.messages) ? pr.messages.map(m => String(m)) : [];
const reply = msgs.join('\n\n');
const amount = Number(pr.payment_amount) || 0;
const summary = String(pr.payment_summary || '');
const amountStr = 'AED ' + amount.toLocaleString('en-US');
const ok = (link.ok === true && !!link.link_url);
let payment_message, payment_header;
if (ok) {
  // Brand-voice format (matches operator-paylink button path):
  //   line 1: the lead-in + link
  //   line 3: AED total · yacht · date · pax (summary already pre-formatted)
  payment_message = 'tap to complete your booking: ' + link.link_url
    + '\n\n' + amountStr + ' · ' + summary;
  payment_header = '💳 PAYMENT LINK — ' + amountStr + '\n'
    + '👤 ' + (pr.customer_name || pr.customer_phone || 'customer')
    + (summary ? ' · ' + summary : '')
    + '\n──────────────';
} else {
  payment_message = reply;
  payment_header = '⚠️ PAYMENT LINK NOT CREATED — '
    + String(link.error || 'unknown error') + '\n'
    + '(draft posted without a link — check the amount / bridge)'
    + '\n──────────────';
}
return [{ json: {
  payment_message: payment_message,
  payment_header: payment_header,
  payment_blocked: !ok
} }];

// /feedback step 2 — assemble the confirmation card text + Yes/Modify/
// No inline keyboard from the classifier's response.
const cls = $json || {};
const raw = $('Process Text Reply').item.json.feedback_text || '';
const chatId = $('Process Text Reply').item.json.admin_chat_id;
if (cls.ok !== true) {
  return [{ json: {
    chat_id: chatId,
    text: '⚠️ Couldn\'t classify that feedback: '
      + (cls.error || 'unknown error') + '\n\n"' + raw + '"',
    reply_markup: { inline_keyboard: [] }
  } }];
}
const pid = cls.proposal_id;
const lines = ['📋 Feedback received:',
               '"' + raw + '"', ''];
const tag = (cls.classification === 'CUSTOMER_NOTE') ? '👤 CUSTOMER NOTE'
          : (cls.classification === 'GLOBAL_RULE')   ? '🌍 GLOBAL RULE'
          : (cls.classification === 'SCENARIO_RULE') ? '🎯 SCENARIO RULE'
          : cls.classification;
lines.push('Classified: ' + tag);
if (cls.classification === 'CUSTOMER_NOTE') {
  if (cls.customer_id) {
    lines.push('For: ' + (cls.customer_name || '(name)')
               + '  (' + cls.customer_id + ')');
  } else if (cls.matches && cls.matches.length > 1) {
    lines.push('⚠️ Multiple customers match "'
               + cls.customer_name + '":');
    for (const m of cls.matches) {
      lines.push('  • ' + m.name + ' — ' + m.customer_id);
    }
    lines.push('Tap Modify and re-type with the explicit phone.');
  } else {
    lines.push('⚠️ No customer record matches "'
               + cls.customer_name + '". Tap Modify to specify.');
  }
} else if (cls.classification === 'SCENARIO_RULE') {
  lines.push('Scenario: ' + (cls.scenario || '(unspecified)'));
}
lines.push('', '→ ' + (cls.summary || cls.text || ''));
const reply_markup = { inline_keyboard: [[
  { text: '✅ Yes',    callback_data: 'feedback_yes:' + pid },
  { text: '✏️ Modify', callback_data: 'feedback_modify:' + pid },
  { text: '❌ No',     callback_data: 'feedback_no:' + pid }
]] };
return [{ json: { chat_id: chatId, text: lines.join('\n'),
                  reply_markup: reply_markup } }];

// Build a [Draft nudge] card with full Send/Edit/Skip buttons. Mirrors
// the Pipeline Hourly Sweep's Build Followup Card pattern so the same
// downstream send chain handles it.
const fu = $('Hermes Draft Followup').item.json || {};
const pc = $('Parse Callback').item.json || {};

const cid    = pc.customer_id;
const label  = fu.label || 'WARM';
const draft  = (fu.draft_text || '').trim();
// Bridge now returns customer_name + notes_for_zayn — use them.
const custName = (fu.customer_name || '').trim();
const reasoning = (fu.notes_for_zayn || '').trim();
const displayName = custName || cid || '?';

const id    = Date.now() + '_' + Math.random().toString(36).slice(2, 7);
const isoNow = new Date().toISOString();

const header = '💡 *NUDGE DRAFT* — ' + displayName + '  (' + label.toLowerCase() + ')';
const body   = '\n\n' + (draft || '⚠️ Hermes returned no draft — skip recommended.');
// Surface Hermes's reasoning so operator sees WHY this draft is the move.
const reasoningLine = reasoning ? ('\n\n📝 _' + reasoning + '_') : '';
const text   = header + body + reasoningLine;

const draftObj = {
  id: id,
  timestamp: isoNow,
  customer_phone: cid,
  customer_name: '',
  customer_message: '',
  conversation_history: '',
  history_count: 0,
  messages: [draft],
  draft_text: draft,
  messages_sent_count: 0,
  notes: reasoning || ('Operator-triggered nudge from /review — label: ' + label),
  telegram_message_id: null,
  telegram_chat_id: 5532831477,
  status: 'pending',
  break_condition: { hit: false },
  is_lead: false,
  is_payment: false,
  is_followup: true,
  followup_silence_window: 'nudge_button',
  followup_silence_hours: null,
  followup_label: label,
  should_send_file: !!(fu && fu.should_send_file),
  file_key: (fu && fu.file_key) || '',
  file_description: (fu && fu.file_description) || '',
};

// BUG-FIX 2026-05-23: also push into staticData pendingQueue so Edit /
// reply-with-feedback / Skip / Send all find the draft via the same
// queue.find() path the customer-msg drafts use. Without this, pressing
// Edit on a nudge card and replying with text falls through Route Text
// Action's awaiting_edit lookup and produces '⚠️ Nothing sent'.
const data = $getWorkflowStaticData('global');
if (!Array.isArray(data.pendingQueue)) data.pendingQueue = [];
data.pendingQueue.push(draftObj);

if (fu && fu.should_send_file && fu.file_key) {
    (lines || []).push('📎 Suggested file: ' + fu.file_key);
  }
  const reply_markup = {
  inline_keyboard: [
    [{ text: '✅ Send', callback_data: 'send:' + id },
     { text: '✏️ Edit', callback_data: 'edit:' + id }],
    [{ text: '🔁 Regen', callback_data: 'regen:' + id },
     { text: '❌ Skip',  callback_data: 'skip:' + id }],
    [{ text: '💳 Send Link', callback_data: 'paylink:' + id }],
      ...((fu && fu.should_send_file && fu.file_key) ? [[{ text: '📎 Send File ('+(fu.file_key)+')', callback_data: 'file:' + id }]] : [])
  ]
};

return {
  json: {
    draft_id: id,
    draft: draftObj,
    telegram_payload: { chat_id: 5532831477, text: text, reply_markup: reply_markup },
    customer_id: cid,
    label: label,
    draft_text: draft,
  }
};

// Dual-write: Save Nudge MsgID updates Redis; this node mirrors the
// telegram_message_id into staticData.pendingQueue so Prep Refine sees
// the real msg_id on the next operator action. Without this, the
// nudge-Edit → text-reply → refine path builds editMessageText JSON
// with `message_id: null`, n8n raises NodeOperationError, and the
// refine silently fails.
const tg = $('Send Nudge Draft').item.json || {};
const msgId = (tg.result && tg.result.message_id) || null;
const draftId = (($('Build Nudge Card').item.json) || {}).draft_id;
if (msgId && draftId) {
  const data = $getWorkflowStaticData('global');
  if (!Array.isArray(data.pendingQueue)) data.pendingQueue = [];
  const entry = data.pendingQueue.find(d => d && d.id === draftId);
  if (entry) entry.telegram_message_id = msgId;
}
return { json: { ok: true, draft_id: draftId, telegram_message_id: msgId } };

// Build the new card text + same inline keyboard for a regenerated followup.
const fu = $('Hermes Regen Followup').item.json || {};
const pc = $('Parse Callback').item.json || {};
const d  = pc.draft || {};

const id    = d.id;
const cid   = d.customer_phone || pc.customer_id;
const label = fu.label || d.followup_label || 'WARM';
const draft = (fu.draft_text || '').trim();

const header = '💡 *NUDGE DRAFT* — ' + (cid || '?') + '  (' + label.toLowerCase() + ')  · regenerated';
const body   = '\n\n' + (draft || '⚠️ Hermes returned no draft — skip recommended.');
const text   = header + body;

if (fu && fu.should_send_file && fu.file_key) {
    (lines || []).push('📎 Suggested file: ' + fu.file_key);
  }
  const reply_markup = {
  inline_keyboard: [
    [{ text: '✅ Send', callback_data: 'send:' + id },
     { text: '✏️ Edit', callback_data: 'edit:' + id }],
    [{ text: '🔁 Regen', callback_data: 'regen:' + id },
     { text: '❌ Skip',  callback_data: 'skip:' + id }],
    [{ text: '💳 Send Link', callback_data: 'paylink:' + id }],
      ...((fu && fu.should_send_file && fu.file_key) ? [[{ text: '📎 Send File ('+(fu.file_key)+')', callback_data: 'file:' + id }]] : [])
  ]
};

return {
  json: {
    draft_id: id,
    customer_id: cid,
    label: label,
    draft_text: draft,
    new_messages: [draft],
    telegram_message_id: d.telegram_message_id,
    telegram_chat_id: d.telegram_chat_id || 5532831477,
    edit_payload: {
      chat_id: d.telegram_chat_id || 5532831477,
      message_id: d.telegram_message_id,
      text: text,
      parse_mode: 'Markdown',
      reply_markup: reply_markup
    }
  }
};

// Operator hit [💳 Send Link] on a draft card. Read the draft
// from Parse Callback (already enriched via staticData + Redis),
// extract amount/customer/summary. Decide: direct call to Nomod
// (if draft already carries an amount > 0) or prompt operator
// for an amount.
const pc = $('Parse Callback').item.json;
const draft = pc.draft || {};
const data = $getWorkflowStaticData('global');
const entry = (data.pendingQueue || []).find(d => d.id === pc.draft_id) || draft;
// Reject if another draft is already awaiting an amount (same lock pattern as awaiting_edit)
const conflict = (data.pendingQueue || []).find(d => d.status === 'awaiting_amount' && d.id !== pc.draft_id);
const cid = entry.customer_phone || pc.customer_id || '';
const name = entry.customer_name || '';
// Build a reasonable payment_summary if not present
let summary = entry.payment_summary || '';
if (!summary) {
  const yacht = (entry.yachts || '').split(',')[0].trim();
  const date = entry.dates || '';
  const pax = entry.party_size || '';
  summary = [yacht, date, pax ? pax + ' guests' : ''].filter(Boolean).join(' · ') || 'Dubriani booking';
}
let amount = 0;
try { amount = parseFloat(entry.payment_amount || draft.payment_amount || 0) || 0; } catch(e) {}
return { json: {
  draft_id: pc.draft_id,
  customer_id: cid,
  customer_name: name,
  payment_summary: summary,
  amount: amount,
  has_amount: amount > 0,
  blocked: !!conflict,
  blocking_phone: conflict ? (conflict.customer_phone || 'unknown') : '',
  chat_id: pc.chat_id,
  message_id: pc.message_id,
  admin_chat_id: 5532831477
} };

// Mark draft awaiting_amount in Redis (bridge mark sets the
// awaiting_amount singleton). Redis-migration 2026-05-28:
// previously staticData-only -> Process Text Reply's Redis
// 'awaiting' lookup couldn't find it -> amount reply ignored.
const prep = $('Prep Paylink').item.json;
if (prep.blocked) {
  return { json: { blocked: true, blocking_phone: prep.blocking_phone,
    chat_id: prep.chat_id, message_id: prep.message_id,
    admin_chat_id: prep.admin_chat_id } };
}
const _http = this.helpers.httpRequest.bind(this.helpers);
async function bq(action, extra) {
  try {
    return await _http({ method: 'POST',
      url: 'http://172.18.0.1:8788/queue',
      headers: { 'Content-Type': 'application/json',
        'X-Bridge-Token': $env.BRIDGE_TOKEN || '' },
      body: Object.assign({ action: action }, extra || {}),
      json: true, timeout: 8000 });
  } catch (e) { return null; }
}
await bq('mark', { draft_id: prep.draft_id, status: 'awaiting_amount' });
return { json: { blocked: false, draft_id: prep.draft_id,
  customer_id: prep.customer_id,
  payment_summary: prep.payment_summary,
  chat_id: prep.chat_id, message_id: prep.message_id,
  admin_chat_id: prep.admin_chat_id } };

