// Read from the unified context ($json from Unify Paylink Context
// upstream, or whatever the upstream node produces in this run).
// $('Log Payment Sent').item exists on the success branch and is
// safe to access here; we just need customer_id + draft_id which
// flow through Log Payment Sent's response.
let cid = '';
let draftId = '';
try {
  const u = $('Unify Paylink Context').item.json;
  cid = u.customer_id || '';
  draftId = u.draft_id || '';
} catch (e) {}
const data = $getWorkflowStaticData('global');
const entry = (data.pendingQueue || []).find(d => d.id === draftId);
if (entry) {
  entry.status = 'link_sent';
  entry.is_payment = true;
  entry.messages_sent_count = (entry.messages_sent_count || 0) + 1;
}
return { json: { ok: true, draft_id: draftId, customer_id: cid,
  draft: { is_payment: true, customer_phone: cid } } };

// One node merges the two paylink paths (button click vs operator
// text reply) into a single $json shape so downstream nodes don't
// need cross-execution lookups like `$('Prep Paylink').item ? ...`.
// In n8n, accessing .item on a node that didn't run in this branch
// THROWS 'Node X hasn't been executed' — kills the chain at body
// evaluation, so the WAHA send never fires and the customer never
// receives the link.
//
// $json on THIS node = the Nomod call response (link_url, link_id,
// amount, ok). Then try each upstream context source; whichever
// actually ran provides the rest.
const nomod = $input.item.json || {};
let ctx = null;
try { ctx = $('Prep Paylink').item.json; } catch (e) { ctx = null; }
if (!ctx) {
  try { ctx = $('Build Paylink From Reply').item.json; } catch (e) { ctx = null; }
}
ctx = ctx || {};
// Pull the operator-facing draft text from staticData so we can
// merge it WITH the payment link in the customer message (was:
// payment link sent alone, without the LLM draft context).
// Also pull the customer_name for operator card display.
let draftText = '';
let custName = '';
try {
  const data = $getWorkflowStaticData('global');
  const entry = (data.pendingQueue || []).find(d => d.id === ctx.draft_id);
  if (entry) {
    draftText = entry.draft_text || '';
    custName = entry.customer_name || '';
  }
} catch (e) {}
return { json: {
  ok: nomod.ok === true,
  link_url: nomod.link_url || '',
  link_id: nomod.link_id || '',
  amount: nomod.amount || ctx.amount || 0,
  error: nomod.error || '',
  draft_id: ctx.draft_id || '',
  customer_id: ctx.customer_id || '',
  customer_name: ctx.customer_name || '',
  payment_summary: ctx.payment_summary || '',
  chat_id: ctx.chat_id || 5532831477,
  message_id: ctx.message_id || null,
  admin_chat_id: ctx.admin_chat_id || 5532831477,
  draft_text: draftText,
  customer_name: custName
} };

