// Read the active draft from Parse Callback's enriched payload to
// pull customer_id, file_key, and a caption. Falls back to scanning
// the pendingQueue staticData by draft_id if needed.
const cb = $('Parse Callback').item.json || {};
const draftId = cb.draft_id;
// Redis draft is the authoritative source post-migration
// (2026-05-28). /assist file-send creates a Redis-ONLY draft (not
// in staticData), so reading staticData alone returned no file_key
// and the send failed. Read the Redis draft first; fall back to
// staticData for legacy drafts.
const d = cb.draft || {};
const queue = ($getWorkflowStaticData('global').pendingQueue) || [];
const sd = queue.find(x => x.id === draftId) || {};
const customerId = cb.customer_id || d.customer_phone || sd.customer_phone;
const fileKey = d.file_key || sd.file_key || cb.file_key || '';
const fileDesc = d.file_description || sd.file_description || '';
const firstMsg = (d.messages && d.messages[0]) || d.draft_text
  || (sd.messages && sd.messages[0]) || sd.draft_text || '';
const caption = (fileDesc && fileDesc.length > 5 ? fileDesc : '')
  || firstMsg || '';

return [{ json: {
  customer_id: customerId,
  draft_id: draftId,
  file_key: fileKey,
  caption: (caption || '').slice(0, 800),
  admin_chat_id: cb.admin_chat_id,
  reply_to_message_id: cb.message_id,
} }];

